import {confirmDelete} from './confirm-delete.js?v=e44c62e47e13';
import {occurrences} from './eternal.mjs?v=e44c62e47e13';
import {mountEternal} from './eternal-ui.js?v=e44c62e47e13';
import {orderNotes} from './note-order.mjs?v=e44c62e47e13';
import {mountLocked} from './locked-ui.js?v=e44c62e47e13';
// The original Temponote layout, rendered with browser APIs instead of React.
export function mount(root,request,{visible=true,selection,locked}={}){
 const confirmController=new AbortController();
 root.innerHTML=`<div class="temponote-workspace notes-only"><main class="app"><header class="header"><div class="brand"><span class="brand-icon" aria-hidden="true">◷</span><h1>TEMPONOTE</h1><time class="current-time" aria-label="Current time"></time></div></header><section class="notes-area" id="note-list" aria-label="Your notes"><div class="notes-wrap"><ol></ol></div></section><footer class="composer"><div class="composer-wrap"><div class="composer-top"><div class="timer-row"><span class="timer-label">KEEP FOR <strong aria-live="polite"></strong> · <time></time></span><button class="reset" hidden>Reset</button></div><div class="time-buttons"><button data-add="60">+1H</button><button data-add="360">+6H</button></div></div><form><label class="sr-only" for="note">Write a note</label><textarea id="note" maxlength="10000" placeholder="Write a note…" rows="2"></textarea><button class="send" type="submit" disabled aria-label="Send note"><svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="m5 12 7-7 7 7M12 5v15"/></svg></button></form><p class="error" role="alert" hidden></p></div></footer></main></div>`;
 const $=s=>root.querySelector(s),input=$('textarea'),list=$('ol'),error=$('.error'),sendButton=$('.send'),sendIcon=sendButton.innerHTML,nodes=new Map(),extending=new Set();
 let notes=[],schedules=[],adjustments={},minutes=60,busy=false,draft=null,offset=0,disposed=false,lastSync=0,loaded=false,selected=selection?.get()||null;
 const tools=document.createElement('div');tools.className='note-tools';$('.composer-top').append(tools);
 $('.time-buttons').append($('.timer-row'));
 const eternal=mountEternal(root,request,{getSchedules:()=>schedules,onChange:load});
 const stopLocked=locked?mountLocked(root,locked):()=>{};
 const duration=m=>[Math.floor(m/60)?Math.floor(m/60)+'H':'',m%60?m%60+'M':''].filter(Boolean).join(' ');
 const format=t=>new Date(t).toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',hour12:true});
 function showError(message=''){if(disposed)return;error.textContent=message;error.hidden=!message;}
 function controls(){input.disabled=busy;sendButton.disabled=busy||!input.value.trim();sendButton.innerHTML=busy?'…':sendIcon;for(const b of root.querySelectorAll('[data-add]'))b.disabled=busy||minutes+Number(b.dataset.add)>525600;$('.reset').disabled=busy;}
 function render(){
  if(disposed||!visible)return;const t=Date.now()+offset,time=$('.current-time'),future=$('.timer-label time');time.textContent=format(t);time.dateTime=new Date(t).toISOString();future.textContent=format(t+minutes*60000);future.dateTime=new Date(t+minutes*60000).toISOString();future.title=new Date(t+minutes*60000).toLocaleString();$('.timer-label strong').textContent=duration(minutes);$('.reset').hidden=minutes<=60;
  const active=orderNotes([...notes.filter(n=>n.expiresAt>t),...occurrences(schedules,t,adjustments)],selected),ids=new Set(active.map(n=>n.id));/* Keep an unseen pin until the notes snapshot arrives; another device may pin before its note loads. */
  for(const [id,li]of nodes)if(!ids.has(id)){li.remove();nodes.delete(id);}
  active.forEach((n,i)=>{
   let li=nodes.get(n.id);if(!li){li=document.createElement('li');li.dataset.id=n.id;li.innerHTML=`<article class="note"><div class="note-heading"><span class="note-pin" aria-hidden="true"><svg width="15" height="15" viewBox="0 0 24 24" fill="currentColor"><path d="M8 2h8v2l-1 1v5l3 3v2h-5v7h-2v-7H6v-2l3-3V5L8 4z"/></svg></span><span class="number"></span><div class="note-body"><p></p></div></div><div class="note-footer"><span class="expiry"></span><div class="note-time-buttons" role="group"><button data-extend="-30">−30M</button><button data-extend="60">+1H</button><button data-extend="360">+6H</button></div><button class="delete" title="Delete note"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/></svg></button></div></article>`;nodes.set(n.id,li);}
   li.querySelector('article').classList.toggle('urgent',n.expiresAt-t<3600000);li.querySelector('article').classList.toggle('eternal',!!n.eternalId);li.querySelector('article').classList.toggle('selected',n.id===selected);const body=li.querySelector('.note-body');body.tabIndex=0;body.setAttribute('role','button');body.setAttribute('aria-pressed',String(n.id===selected));body.setAttribute('aria-label',(n.id===selected?'Unpin note: ':'Move note to top: ')+n.body);li.querySelector('.number').textContent=(i+1)+'.';if(li.querySelector('p').textContent!==n.body)li.querySelector('p').textContent=n.body;
   const expiry=li.querySelector('.expiry'),seconds=Math.ceil((n.expiresAt-t)/1000);expiry.textContent=(seconds<60?seconds+'S':duration(Math.ceil(seconds/60)))+' LEFT';expiry.title='Expires '+new Date(n.expiresAt).toLocaleString();li.querySelector('[role=group]').setAttribute('aria-label','Adjust time for note '+(i+1));li.querySelector('.delete').setAttribute('aria-label','Delete note '+(i+1));for(const b of li.querySelectorAll('button'))b.disabled=extending.has(n.id);if(list.children[i]!==li)list.insertBefore(li,list.children[i]||null);
  });
 }
 function selectNote(event){if(event.target.closest('button'))return;const li=event.target.closest('li');if(!li)return;if(event.type==='keydown'){if(event.key!=='Enter'&&event.key!==' ')return;event.preventDefault();if(event.repeat)return;}else if(window.getSelection()?.toString())return;const next=selected===li.dataset.id?null:li.dataset.id;selected=next;render();selection?.set(next);if(next)$('#note-list').scrollTo({top:0,behavior:'instant'});}
 async function load(){const start=Date.now();try{const r=await request('/api/notes',{cache:'no-store'});if(!r.ok)throw Error('Could not sync notes. Please refresh or sign in again.');const data=await r.json();if(disposed||start<lastSync)return;lastSync=start;offset=data.serverNow-Date.now();notes=data.notes;schedules=data.eternalNotes||[];adjustments=data.eternalAdjustments||{};loaded=true;eternal.render();render();showError();}catch(e){showError(e.message);}}
 async function send(){if(busy||!input.value.trim())return;busy=true;showError();controls();try{draft??=crypto.randomUUID();const r=await request('/api/notes',{method:'POST',body:JSON.stringify({body:input.value,minutes,id:draft})});if(!r.ok)throw Error('Could not save. Your note is still here. Try again.');if(disposed)return;input.value='';minutes=60;draft=null;lastSync=Date.now();await load();$('#note-list').scrollTo({top:0,behavior:'smooth'});input.disabled=false;input.focus();}catch(e){showError(e.message);}finally{busy=false;if(!disposed){controls();render();}}}
 async function act(event){const button=event.target.closest('button'),li=button?.closest('li');if(!li)return;const id=li.dataset.id;if(extending.has(id))return;const extra=Number(button.dataset.extend),scheduled=occurrences(schedules,Date.now()+offset,adjustments).find(n=>n.id===id);if(!button.classList.contains('delete')&&!extra)return;if(!extra&&!await confirmDelete(scheduled?'REMOVE THIS ETERNAL NOTE FOR TODAY?':'DELETE THIS NOTE?',confirmController.signal))return;if(disposed)return;extending.add(id);render();try{const r=await request(scheduled?'/api/eternal':extra?'/api/notes':'/api/notes?id='+encodeURIComponent(id),scheduled?{method:'PATCH',body:JSON.stringify(extra?{id:scheduled.eternalId,occurrenceId:id,minutes:extra}:{id:scheduled.eternalId,dismiss:true})}:extra?{method:'PATCH',body:JSON.stringify({id,minutes:extra})}:{method:'DELETE'});const result=await r.json();if(!r.ok)throw Error(result.error||'Could not save. Try again.');if(disposed)return;lastSync=Date.now();if(scheduled){if(extra&&selected===id&&result.id){selected=result.id;selection?.set(selected);}await load();}else if(extra){offset=result.serverNow-Date.now();notes=notes.map(n=>n.id===id?{...n,expiresAt:result.expiresAt}:n);}else notes=notes.filter(n=>n.id!==id);showError();}catch(e){showError(e.message);}finally{extending.delete(id);render();}}
 input.addEventListener('input',()=>{draft=null;controls();});input.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send();}});$('.composer-wrap>form').addEventListener('submit',e=>{e.preventDefault();send();});$('.reset').addEventListener('click',()=>{minutes=60;render();});for(const b of root.querySelectorAll('[data-add]'))b.addEventListener('click',()=>{minutes+=Number(b.dataset.add);render();controls();});list.addEventListener('click',act);
 const stopSelection=selection?.subscribe?.(id=>{if(selected===id)return;selected=id;render();});
 list.addEventListener('click',selectNote);list.addEventListener('keydown',selectNote);
 let refreshPending=false;const refresh=()=>{if(visible&&!document.hidden&&!refreshPending){refreshPending=true;load().finally(()=>{refreshPending=false;});}},visibility=event=>{visible=event.detail;if(visible){render();refresh();}};document.addEventListener('visibilitychange',refresh);window.addEventListener('focus',refresh);window.addEventListener('temponotes-visibility',visibility);const sync=setInterval(refresh,10000),clock=setInterval(render,1000);render();load();
 return ()=>{disposed=true;confirmController.abort();stopSelection?.();eternal.dispose();stopLocked();clearInterval(sync);clearInterval(clock);document.removeEventListener('visibilitychange',refresh);window.removeEventListener('focus',refresh);window.removeEventListener('temponotes-visibility',visibility);root.replaceChildren();nodes.clear();notes=[];schedules=[];};
}
